    try:
        got = engine.execute(query)["rows"]
    except SQLRuntimeError:
        return  # division or modulo by zero: SQLite yields NULL instead
    if ordered:
        assert got == expected, query
    else:
        assert _multiset(got) == _multiset(expected), query
