        if not (isinstance(on, n.Binary) and on.op == "="
                and isinstance(on.left, n.ColumnRef) and isinstance(on.right, n.ColumnRef)):
            return None
        a, b = self.scope.lookup(on.left), self.scope.lookup(on.right)
        if a is None or b is None:
            return None  # an outer reference
        right = self.scope.sources[k - 1]
        if a[0] == k - 1 and b[0] < k - 1:
            a, b = b, a
        if b[0] != k - 1 or a[0] >= k - 1:
            return None
        return a[1], b[1] - right.offset

    def _bind_items(self) -> None:
        for item in self.stmt.items:
            if isinstance(item, n.Star):
                if self.stmt.from_ is None:
                    raise SQLSyntaxError("SELECT * requires FROM")
                if self.grouped:
                    raise SQLSyntaxError("* is not allowed in a grouped query")
                sources = (self.scope.sources if item.table is None
                           else [self.scope.source(item.table)])
                for src in sources:
                    for i, name in enumerate(src.columns):
                        idx = src.offset + i
                        self.columns.append(name)
                        self.item_fns.append(lambda env, idx=idx: env[idx])
                continue
            if self.stmt.distinct:
                raise SQLSyntaxError("with SELECT DISTINCT, ORDER BY items must be output "
                                     "columns")
            self.sort_keys.append((None, self.compiler.compile(item.expr), item.desc))

    # ------------------------------------------------------------ execution

    def _source_rows(self) -> list[tuple]:
        if not self.sources:
            return [()]
        rows = [tuple(r) for r in self.sources[0].rows()]
        for source, src_scope, (kind, pred, equi) in zip(self.sources[1:],
                                                         self.scope.sources[1:], self.joins):
            right = source.rows()
            nulls = (None,) * len(src_scope.columns)
            if equi is not None:
                rows = _hash_join(rows, right, equi, kind == "LEFT", nulls)
                continue
            joined = []
            for left in rows:
                matched = False
                for r in right:
                    combined = left + r
                    if pred is None or pred(combined):
                        joined.append(combined)
                        matched = True
                if kind == "LEFT" and not matched:
                    joined.append(left + nulls)
            rows = joined
        return rows

    def run(self) -> list[tuple]:
        rows = self._source_rows()
        if self.where is not None:
            where = self.where
            rows = [r for r in rows if where(r)]
        item_fns = self.item_fns
        key_fns = [fn for _, fn, _ in self.sort_keys if fn is not None]

